from pathlib import Path
import re

p=Path('app/src/main/java/com/sakhtemanyar/MainActivity.java')
s=p.read_text()

def replace_method(name,new):
    global s
    start=s.index('    void '+name+'(')
    i=s.index('{',start); depth=0; end=None
    for k in range(i,len(s)):
        if s[k]=='{': depth+=1
        elif s[k]=='}':
            depth-=1
            if depth==0:
                end=k+1; break
    s=s[:start]+new+s[end:]

replace_method('frame', '''    void frame(String title,boolean inner){screenToken++; FrameLayout fr=new FrameLayout(this); fr.setBackgroundColor(bg); fr.setLayoutDirection(View.LAYOUT_DIRECTION_RTL); setContentView(fr); root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setBackgroundColor(bg); LinearLayout bar=new LinearLayout(this); bar.setGravity(Gravity.CENTER_VERTICAL); bar.setPadding(dp(9),dp(7),dp(9),dp(7)); bar.setBackground(grad(navy,navy2,0)); TextView nav=tv(inner?"‹":"☰",31,white); nav.setGravity(Gravity.CENTER); bar.addView(nav,new LinearLayout.LayoutParams(dp(52),dp(50))); TextView t=tv(title,18,white); t.setTypeface(Typeface.DEFAULT,Typeface.BOLD); bar.addView(t,new LinearLayout.LayoutParams(0,dp(50),1)); TextView brand=tv("ساختمان‌یار",12,Color.rgb(190,224,220)); brand.setGravity(Gravity.CENTER); bar.addView(brand,new LinearLayout.LayoutParams(dp(92),dp(50))); root.addView(bar,new LinearLayout.LayoutParams(-1,dp(66))); ScrollView sv=new ScrollView(this); sv.setFillViewport(true); content=new LinearLayout(this); content.setOrientation(LinearLayout.VERTICAL); content.setPadding(dp(16),dp(16),dp(16),dp(32)); content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL); sv.addView(content); root.addView(sv,new LinearLayout.LayoutParams(-1,0,1)); fr.addView(root,new FrameLayout.LayoutParams(-1,-1)); drawer=new LinearLayout(this); drawer.setOrientation(LinearLayout.VERTICAL); drawer.setPadding(dp(14),dp(16),dp(14),dp(22)); drawer.setBackgroundColor(white); drawer.setLayoutDirection(View.LAYOUT_DIRECTION_RTL); FrameLayout.LayoutParams dl=new FrameLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.90),-1,Gravity.RIGHT); fr.addView(drawer,dl); drawer.setVisibility(View.GONE); nav.setOnClickListener(v->{if(inner)backPage();else toggleDrawer();}); }''')

