replace_method('chargeDialog', '''    void chargeDialog(){final EditText t=input("عنوان هزینه / شارژ"),a=input("مبلغ کل به تومان"),d=input("توضیحات");LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(10),0,dp(10),0);for(EditText e:new EditText[]{t,a,d}){l.addView(e,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));}new AlertDialog.Builder(this).setTitle("ثبت شارژ / هزینه").setView(l).setNegativeButton("لغو",null).setPositiveButton("ادامه",(x,w)->chooseChargeAllocation(t.getText().toString(),a.getText().toString(),d.getText().toString())).show(); }\n    void chooseChargeAllocation(String title,String amount,String desc){call("dashboard",j->{JSONArray us=j.optJSONArray("units");if(us==null||us.length()==0){toast("ابتدا واحدها را ثبت کنید");return;}String[] labels=new String[us.length()];for(int i=0;i<us.length();i++){JSONObject u=us.optJSONObject(i);labels[i]="واحد "+u.optString("unit_no")+" • "+u.optInt("resident_count",0)+" نفر";}new AlertDialog.Builder(this).setTitle("نحوه تعلق هزینه").setSingleChoiceItems(new String[]{"مساوی بین واحدها","بر اساس تعداد نفرات"},0,(d,w)->{}).setMultiChoiceItems(labels,null,(d,w,checked)->{}).setNegativeButton("لغو",null).setPositiveButton("ثبت برای واحدهای انتخاب‌شده",(d,w)->{AlertDialog q=(AlertDialog)d;int mode=q.getListView().getCheckedItemPosition();ArrayList<String> ids=new ArrayList<>();for(int i=0;i<us.length();i++)if(q.getListView().isItemChecked(i))ids.add(us.optJSONObject(i).optString("id"));if(ids.isEmpty()){toast("حداقل یک واحد را انتخاب کنید");return;}long rial=Math.max(0,parseMoney(amount)*10);callObj(new JSONObject().put("action","add_charge").put("title",title).put("amount_rial",rial).put("description",desc).put("allocation_method",mode==1?"per_person":"per_unit").put("unit_ids",new JSONArray(ids)),z->{toast("هزینه ثبت شد و فقط برای واحدهای انتخاب‌شده تعلق گرفت");charges();});}).show();});}''')

replace_method('repairDialog', '''    void repairDialog(){final EditText t=input("عنوان تعمیر"),a=input("هزینه کل به تومان"),d=input("توضیحات");LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(10),0,dp(10),0);for(EditText e:new EditText[]{t,a,d}){l.addView(e,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));}new AlertDialog.Builder(this).setTitle("ثبت تعمیر").setView(l).setNegativeButton("لغو",null).setPositiveButton("انتخاب واحدها",(x,w)->chooseRepairUnits(t.getText().toString(),a.getText().toString(),d.getText().toString())).show(); }\n    void chooseRepairUnits(String title,String amount,String desc){call("dashboard",j->{JSONArray us=j.optJSONArray("units");if(us==null||us.length()==0){toast("ابتدا واحدها را ثبت کنید");return;}String[] labels=new String[us.length()];for(int i=0;i<us.length();i++)labels[i]="واحد "+us.optJSONObject(i).optString("unit_no");new AlertDialog.Builder(this).setTitle("تعمیر برای کدام واحدها؟").setMultiChoiceItems(labels,null,(d,w,c)->{}).setNegativeButton("لغو",null).setPositiveButton("ثبت تعمیر",(d,w)->{AlertDialog q=(AlertDialog)d;ArrayList<String> ids=new ArrayList<>();for(int i=0;i<us.length();i++)if(q.getListView().isItemChecked(i))ids.add(us.optJSONObject(i).optString("id"));if(ids.isEmpty()){toast("حداقل یک واحد را انتخاب کنید");return;}long rial=Math.max(0,parseMoney(amount)*10);callObj(new JSONObject().put("action","add_repair").put("title",title).put("amount_rial",rial).put("description",desc).put("unit_ids",new JSONArray(ids)),z->{toast("تعمیر ثبت شد");repairs();});}).show();});}''')

replace_method('repairs', '''    void repairs(){frame("تعمیرات",true);managerDrawer();section("تعمیرات","هر مورد را لمس کنید تا جزئیات، واحدها، فیش و عملیات مدیریتی باز شود");Button add=btn("＋ ثبت تعمیر جدید",red);content.addView(add,new LinearLayout.LayoutParams(-1,dp(54)));content.addView(gap(12));add.setOnClickListener(v->repairDialog());call("dashboard",j->{JSONArray a=j.optJSONArray("repairs");if(a==null||a.length()==0){empty("هنوز تعمیراتی ثبت نشده است");return;}section("سوابق تعمیرات",null);for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)repairCard(x);}});}\n    void repairCard(JSONObject x){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(13),dp(15),dp(13));c.setBackground(box(white,19));TextView h=tv(x.optString("title","تعمیرات"),17,navy);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);c.addView(h);c.addView(tv(money(x.optDouble("amount"))+"  •  "+JalaliDate.format(x.optString("created_at")),13,muted));c.addView(tv("برای واحدهای مشخص‌شده • وضعیت: "+statusFa(x.optString("status")),12,statusColor(x.optString("status"))));Button b=btn("مشاهده جزئیات  ›",blue);c.addView(b,new LinearLayout.LayoutParams(-1,dp(47)));b.setOnClickListener(v->repairDetails(x));content.addView(c,new LinearLayout.LayoutParams(-1,dp(142)));content.addView(gap(10));}\n    void repairDetails(JSONObject x){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(8),dp(4),dp(8),dp(4));l.addView(tv("مبلغ: "+money(x.optDouble("amount")),15,navy));l.addView(tv("توضیحات: "+x.optString("description","-"),14,muted));l.addView(tv("واحدها: از اطلاعات تخصیص ثبت‌شده",14,muted));if(!x.optString("receipt_url","").isEmpty())l.addView(tv("فیش / عکس تعمیر ثبت شده است",13,green));new AlertDialog.Builder(this).setTitle(x.optString("title","تعمیرات")).setView(l).setNegativeButton("بستن",null).setNeutralButton("حذف / ابطال",(d,w)->callObj(new JSONObject().put("action","delete_repair").put("repair_id",x.optString("id")),z->{toast("تعمیر حذف شد");repairs();})).setPositiveButton("ویرایش",(d,w)->editRepair(x)).show();}\n    void editRepair(JSONObject x){final EditText t=input("عنوان"),a=input("مبلغ تومان"),d=input("توضیحات");t.setText(x.optString("title",""));a.setText(String.valueOf(Math.round(x.optDouble("amount")/10.0)));d.setText(x.optString("description",""));LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);for(EditText e:new EditText[]{t,a,d}){l.addView(e,new LinearLayout.LayoutParams(-1,dp(54)));l.addView(gap(7));}new AlertDialog.Builder(this).setTitle("ویرایش تعمیر").setView(l).setNegativeButton("لغو",null).setPositiveButton("ذخیره",(q,w)->callObj(new JSONObject().put("action","update_repair").put("repair_id",x.optString("id")).put("title",t.getText().toString()).put("amount_rial",parseMoney(a.getText().toString())*10).put("description",d.getText().toString()),z->{toast("تعمیر ویرایش شد");repairs();})).show();}''')

